<script setup lang="ts">
import {computed,ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {storedValueActivityApi} from '@/shared/stored-value-activity-owner';import {managementGo} from '@/shared/management';import {currentCurrency,money} from '@shared/utils/money';import type {SvActivity} from '@/api/stored-value-governance';
const brand=ref('');const owner=computed(()=>brand.value||store.value);const activityApi=computed(()=>storedValueActivityApi(api,!!brand.value));
const {t}=useI18n();const m=ref(''),store=ref(''),items=ref<SvActivity[]>([]),loading=ref(true),failed=ref(false),error=ref(''),page=ref(1),more=ref(false);const currency=ref(currentCurrency());let generation=0;
async function load(append=false){if(!m.value||!owner.value)return;const g=++generation;loading.value=true;failed.value=false;try{if(!append){const context=await activityApi.value.mSvActivityContext(owner.value,{managementNo:m.value,currency:currency.value,intent:'READ'});currency.value=context.currency;}const next=append?page.value+1:1;const result=await activityApi.value.mSvActivities(owner.value,{managementNo:m.value,currency:currency.value,page:next,size:20});if(g!==generation)return;items.value=append?[...items.value,...result.records]:result.records;page.value=next;more.value=items.value.length<result.total;}catch(e){failed.value=true;error.value=(e as Error).message}finally{if(g===generation)loading.value=false}}
function go(no?:string){managementGo('storedValueActivityEdit',{m:m.value,...(brand.value?{b:brand.value}:{s:store.value}),a:no})}
onLoad(q=>{m.value=q?.m||'';store.value=q?.s||'';brand.value=q?.b||'';void load()});onShow(()=>{if(m.value&&owner.value)void load()});
</script>
<template><sh-scaffold title-key="svGov.activities" :pending="loading&&!items.length" :failed="failed" @retry="load(false)"><view v-for="a in items" :key="a.activityNo" class="sh-card sh-hit" @tap="go(a.activityNo)"><view class="sh-row sh-row--between"><text class="txt-title">{{a.definition.name}}</text><text class="sh-chip">{{t(`svGov.states.${a.status}`)}}</text></view><sh-kv v-for="tier in a.definition.rule.tiers" :key="tier.tierNo" :label="money(tier.payAmountMinor,a.definition.currency)" between>{{t('svGov.give')}} {{money(tier.bonusAmountMinor,a.definition.currency)}}</sh-kv></view><sh-empty v-if="!loading&&!items.length" :text="t('svGov.noActivities')"/><text v-if="error" class="sh-hint">{{error}}</text><view v-if="more&&!loading" class="sh-btn sh-btn--soft" @tap="load(true)">{{t('svGov.more')}}</view><sh-actionbar><view class="sh-btn" @tap="go()">{{t('svGov.createActivity')}}</view></sh-actionbar></sh-scaffold></template>
